<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Inertia\Inertia; class AuthController extends Controller {public function show(){return Inertia::render('Auth/Login');} public function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($c))return back()->withErrors(['email'=>'Invalid credentials.']);$r->session()->regenerate();return redirect()->route('dashboard');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}}
